        return (
          <Box
            key={tier}
            onClick={() => handleSwitchTier(tier as TierLevel)}
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 0.6,
              px: 1.2,
              py: 0.5,
              borderRadius: "4px",
