              bgcolor: isSelected ? "#FFFFFF" : defaultBg,
              border: isSelected ? "1.5px solid #0000FF" : "1px solid transparent",
              color: isSelected ? "#0000FF" : defaultColor,
              fontSize: "12px",
              fontWeight: 700,
              fontFamily: "var(--font-cairo), Cairo, sans-serif",
              transition: "all 0.15s ease",
              "&:hover": {
                opacity: 0.9,
